class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

        self.set_warm_up(110, Resolution.DAILY)

    def on_data(self, data: Slice):
        bars = data.bars

        if bars.contains_key(self.spy):
            spy_bar = bars[self.spy]
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)

        if bars.contains_key(self.aapl):
            aapl_bar = bars[self.aapl]
            if self.previous_aapl_close is not None:
                if aapl_bar.close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        all_bars_present = all(bars.contains_key(symbol) for symbol in self.symbols)
        if all_bars_present and not self.is_warming_up:
            self._evaluate_strategy_a(bars[self.spy].close)
            self._evaluate_strategy_b(bars[self.aapl].close)

        if bars.contains_key(self.spy) and self.spy_sma.is_ready:
            self.previous_spy_close = bars[self.spy].close
            self.previous_spy_sma = self.spy_sma.current.value

    def _evaluate_strategy_a(self, close):
        if self.previous_spy_close is None or self.previous_spy_sma is None:
            return

        sma = self.spy_sma.current.value
        crosses_above = (
            self.previous_spy_close <= self.previous_spy_sma and close > sma
        )
        crosses_below = (
            self.previous_spy_close >= self.previous_spy_sma and close < sma
        )

        if self.strategy_a_shares > 0:
            if crosses_below and not self.strategy_a_pending:
                self.strategy_a_pending = True
                self.market_order(
                    self.spy, -self.strategy_a_shares, tag="STRATEGY_A_SELL"
                )
        elif crosses_above and not self.strategy_a_pending:
            quantity = self.calculate_order_quantity(self.spy, 0.40)
            if quantity > 0:
                self.strategy_a_pending = True
                self.market_order(self.spy, quantity, tag="STRATEGY_A_BUY")

    def _evaluate_strategy_b(self, close):
        if not self.aapl_rsi.is_ready:
            return

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.current.value > 60 and not self.strategy_b_pending:
                self.strategy_b_pending = True
                self.market_order(
                    self.aapl, -self.strategy_b_shares, tag="STRATEGY_B_SELL"
                )
        elif self.aapl_red_streak >= 3 and not self.strategy_b_pending:
            allocation = 20_000
            if self.portfolio.cash >= allocation:
                quantity = int(allocation // close)
                if quantity > 0:
                    self.strategy_b_pending = True
                    self.market_order(self.aapl, quantity, tag="STRATEGY_B_BUY")

    def on_order_event(self, order_event: OrderEvent):
        order = self.transactions.get_order_by_id(order_event.order_id)
        if order is None:
            return

        fill_quantity = order_event.fill_quantity
        if order.tag == "STRATEGY_A_BUY":
            self.strategy_a_shares += max(0, fill_quantity)
        elif order.tag == "STRATEGY_A_SELL":
            self.strategy_a_shares = max(
                0, self.strategy_a_shares - abs(fill_quantity)
            )
        elif order.tag == "STRATEGY_B_BUY":
            self.strategy_b_shares += max(0, fill_quantity)
        elif order.tag == "STRATEGY_B_SELL":
            self.strategy_b_shares = max(
                0, self.strategy_b_shares - abs(fill_quantity)
            )

        if order_event.status in [OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID]:
            if order.tag.startswith("STRATEGY_A_"):
                self.strategy_a_pending = False
            elif order.tag.startswith("STRATEGY_B_"):
                self.strategy_b_pending = False

