                    cash_to_invest = 20000
                    if self.Portfolio.Cash >= cash_to_invest:
                        shares = int(math.floor(cash_to_invest / aapl_close))
                        if shares > 0:
                            self.MarketOrder(aapl, shares)
                            self.strategy_b_shares = shares

        if data.Bars.ContainsKey(spy) and self.spy_sma.IsReady:
