class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}

        # The extra observation supplies the prior fully formed SMA needed to
        # evaluate a crossing on the first live bar.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue to consume every bar that exists,
        # independently of whether this Slice is complete.
        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        complete_slice = len(bars) == len(self.symbols)
        indicators_ready = self.spy_sma.IsReady and self.aapl_rsi.IsReady
        spy_cross_ready = self.previous_spy_close is not None and self.previous_spy_sma is not None

        if complete_slice and not self.IsWarmingUp and indicators_ready and spy_cross_ready:
            self._evaluate_spy(spy_bar.Close)
            self._evaluate_aapl(aapl_bar.Close)

        if spy_bar is not None and self.spy_sma.IsReady:
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = self.spy_sma.Current.Value
        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def _evaluate_spy(self, close):
        symbol = self.symbols["SPY"]
        if symbol in self.pending_orders:
            return

        sma = self.spy_sma.Current.Value
        crossed_below = self.previous_spy_close >= self.previous_spy_sma and close < sma
        crossed_above = self.previous_spy_close <= self.previous_spy_sma and close > sma

        # Sells are evaluated before buys.
        if self.spy_lot > 0:
            if crossed_below:
                ticket = self.MarketOrder(symbol, -self.spy_lot)
                self.pending_orders[symbol] = ticket.OrderId
            return

        if crossed_above:
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // close)
            if quantity > 0:
                ticket = self.MarketOrder(symbol, quantity)
                self.pending_orders[symbol] = ticket.OrderId

    def _evaluate_aapl(self, close):
        symbol = self.symbols["AAPL"]
        if symbol in self.pending_orders:
            return

        # Sells are evaluated before buys.
        if self.aapl_lot > 0:
            if self.aapl_rsi.Current.Value > 60:
                ticket = self.MarketOrder(symbol, -self.aapl_lot)
                self.pending_orders[symbol] = ticket.OrderId
            return

        allocation = 20_000
        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= allocation:
            quantity = int(allocation // close)
            if quantity > 0:
                ticket = self.MarketOrder(symbol, quantity)
                self.pending_orders[symbol] = ticket.OrderId

    def OnOrderEvent(self, order_event: OrderEvent):
        symbol = order_event.Symbol
        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if symbol == self.symbols["SPY"]:
                self.spy_lot += int(order_event.FillQuantity)
            elif symbol == self.symbols["AAPL"]:
                self.aapl_lot += int(order_event.FillQuantity)

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            if self.pending_orders.get(symbol) == order_event.OrderId:
                del self.pending_orders[symbol]

