        if self.strategy_b_shares > 0:
            if float(self.aapl_rsi.Current.Value) > 60.0:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
        elif self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000.0:
            shares = floor(20_000.0 / float(aapl_bar.Close))
            if shares > 0:
                self.MarketOrder(self.symbols["AAPL"], shares)
                self.strategy_b_shares = shares

    def _bar(self, data, ticker):
        symbol = self.symbols[ticker]
        return data.Bars[symbol] if data.Bars.ContainsKey(symbol) else None

